import React, { useState, useEffect } from 'react';
import axios from 'axios';
import ProductCard from '../components/ProductCard';
import { useAuth } from '../context/AuthContext'; // Import the Auth Brain

const Home = () => {
    const [products, setProducts] = useState([]);
    const [loading, setLoading] = useState(true);
    const { user } = useAuth(); // Access the logged-in user

    useEffect(() => {
        const fetchProducts = async () => {
            try {
                const { data } = await axios.get('http://localhost:5000/api/products');
                setProducts(data);
                setLoading(false);
            } catch (error) {
                console.error("Error fetching luxury goods:", error);
                setLoading(false);
            }
        };
        fetchProducts();
    }, []);

    // --- NEW: Payment Handler Function ---
    const handlePurchase = async (product) => {
        if (!user) {
            alert("Please Sign In to acquire this piece.");
            return;
        }

        try {
            // 1. Get Firebase ID Token (The secure passport)
            const token = await user.getIdToken();

            // 2. Create Order on Node.js Server
            const { data: order } = await axios.post(
                'http://localhost:5000/api/payment/create-order', // Fixed URL: /api/payment NOT /api/payments
                { amount: product.price },
                { headers: { Authorization: `Bearer ${token}` } }
            );

            // 3. Open Razorpay Modal
            const options = {
                key: process.env.REACT_APP_RAZORPAY_KEY_ID || "YOUR_TEST_KEY_ID", // Use Env Var
                amount: order.amount,
                currency: order.currency || "INR",
                name: "BINDASS!! Co.",
                description: product.name,
                order_id: order.id,
                handler: async (response) => {
                    // 4. Verify Payment Signature
                    const verifyData = {
                        ...response,
                        orderDetails: { productId: product._id, price: product.price }
                    };
                    await axios.post('http://localhost:5000/api/payment/verify', verifyData, { // Fixed URL: /api/payment/verify
                        headers: { Authorization: `Bearer ${token}` }
                    });
                    alert("Order Placed! Check your email for the luxury invoice.");
                },
                theme: { color: "#000000" } // Minimalist aesthetic
            };

            const rzp = new window.Razorpay(options);
            rzp.open();
        } catch (err) {
            console.error("Payment initiation failed:", err);
            alert("Transaction could not be initialized.");
        }
    };

    if (loading) return <div className="text-center py-20 font-serif">Loading Collection...</div>;

    return (
        <div className="bg-white">
            <div className="mx-auto max-w-2xl px-4 py-16 sm:px-6 sm:py-24 lg:max-w-7xl lg:px-8">
                <h2 className="text-2xl font-serif tracking-tight text-gray-900 mb-8 uppercase letter-spacing-widest">
                    New Arrivals
                </h2>
                <div className="grid grid-cols-1 gap-x-6 gap-y-10 sm:grid-cols-2 lg:grid-cols-4 xl:gap-x-8">
                    {products.map((product) => (
                        <ProductCard
                            key={product._id}
                            product={product}
                            onBuy={() => handlePurchase(product)} // Pass the function down
                        />
                    ))}
                </div>
            </div>
        </div>
    );
};

export default Home;
